import { Cents, PaymentId, TenantId } from '../../core/src';

export interface ChargeInput {
  paymentId: PaymentId;
  tenantId: TenantId;
  amountCents: Cents;
}

export interface PaymentAttempt extends ChargeInput {
  state: 'captured' | 'rejected' | 'refunded';
  reason?: string;
}

export interface Refund {
  paymentId: PaymentId;
  amountCents: Cents;
}

export type ChargeResult = { ok: true } | { ok: false; reason: string };

export interface PaymentGateway {
  charge(input: ChargeInput): ChargeResult;
  refund(paymentId: PaymentId, amountCents: Cents): void;
}

import { Cents, assertCents, discountCents, multiplyCents } from '../../core/src';

export interface PriceInput {
  unitPriceCents: Cents;
  quantity: number;
  promotionBps: number;
}

export interface PriceBreakdown {
  subtotalCents: Cents;
  discountCents: Cents;
  shippingCents: Cents;
  totalCents: Cents;
}

const FREE_SHIPPING_CENTS = 5_000;
const SHIPPING_CENTS = 1_000;

export function price(input: PriceInput): PriceBreakdown {
  const subtotalCents = multiplyCents(input.unitPriceCents, input.quantity);
  const promotionDiscount = discountCents(subtotalCents, input.promotionBps);
  const discounted = subtotalCents - promotionDiscount;
  const shippingCents = discounted >= FREE_SHIPPING_CENTS ? 0 : SHIPPING_CENTS;
  return {
    subtotalCents,
    discountCents: promotionDiscount,
    shippingCents,
    totalCents: assertCents(discounted + shippingCents),
  };
}

import { Inventory } from '../../catalog/src';
import { Clock, IdSource } from '../../core/src';
import { Outbox } from '../../fulfillment/src';
import { CancellationService } from './cancellation-service';
import { CheckoutService } from './checkout-service';
import { FakePaymentGateway } from './fake-payment';
import { OrderRepository } from './order-repository';

export function createCommerceSystem(dependencies: { now: () => number; ids: IdSource }) {
  const inventory = new Inventory();
  const payments = new FakePaymentGateway();
  const orders = new OrderRepository();
  const outbox = new Outbox();
  const clock: Clock = { now: dependencies.now };
  return {
    inventory,
    payments,
    orders,
    outbox,
    checkout: new CheckoutService(inventory, payments, orders, outbox, clock, dependencies.ids),
    cancellation: new CancellationService(orders, payments, inventory),
  };
}

